'use strict';
const SIM=!!window.POOM_SIM, NS=SIM?'poom-sim':'poom', VERSION='1.1.0', BUILD='5ebee68e', KEY=NS+'.db';
const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
