const head=t=>`<div class="row"><button class="icb" data-a="back" aria-label="뒤로" style="margin-left:-10px">${I.back}</button><div class="ptitle grow">${t}</div></div>`;
function vEmergency(){const p=db.profile,t=today(),g=ga(t),li=lastInjection(),meds=db.meds.filter(m=>active(m,t));const reds=[];
 if(g!=null&&!born()){if(g<49&&!db.checks.us1)reds.push('early');if(meds.some(m=>m.type==='injection'||/아스피린/.test(m.name)))reds.push('anti');reds.push('clot');if(g>=140)reds.push('pre');if(g>=140&&g<259)reds.push('labor')}if(born()&&diff(t,p.birthDate)<=84)reds.push('pp');reds.push('any');
 const tel=(n)=>n?`<a href="tel:${esc(n.replace(/[^0-9+]/g,''))}">${esc(n)}</a>`:'<span class="faint">설정에서 입력</span>';
 const r=(a,b)=>`<div class="li" style="min-height:44px"><span class="small muted" style="width:88px;flex:none">${a}</span><span class="grow">${b}</span></div>`;
 return `<div class="stack">${head('응급 카드')}<div class="list">${r('이름',esc(p.name)||'-')}${g!=null&&!born()?r('임신 주수',`${fmtGA(g)} · 예정일 ${fmtYMD(edd())}`):''}${r('아기 수',p.fetus&&p.fetus!=='unknown'?esc(p.fetus)+'명':'미확인')}${r('혈액형',esc((p.blood||'')+(p.rh||''))||'미입력')}${p.allergy?r('약 알레르기',esc(p.allergy)):''}${r('마지막 주사',li?`${esc(li.name)} ${esc(li.dose||'')}<br><b class="num">${fmtYMD(li.date)} ${esc(li.at||'시각 미기록')}</b>`:'기록 없음')}</div><section class="sec"><h2 style="font-size:1rem">현재 약</h2><div class="list">${meds.map(m=>`<div class="li" style="min-height:44px"><span class="tag t-${m.type}">${TYPE[m.type]}</span><span class="grow">${esc(m.name)} ${esc(m.dose||'')}</span></div>`).join('')||'<div class="li"><span class="s">없음</span></div>'}</div></section><section class="sec"><h2 style="font-size:1rem">연락처</h2><div class="list">${r(esc(p.hospital||'담당 병원'),tel(p.hospitalTel))}${p.prevHospital?r(esc(p.prevHospital)+'<br><span class="small muted">이전 병원</span>',tel(p.prevHospitalTel)):''}${r(esc(p.guardian||'보호자'),tel(p.guardianTel))}${r('응급','<a href="tel:119">119</a>')}</div></section><section class="sec"><h2 style="font-size:1rem">바로 연락할 신호</h2><div class="prose">${(gloOff=true,reds.map(k=>lst('w',RED[k].t,RED[k].items)).join(''))}${(gloOff=false,'')}</div></section><div class="small faint">이 화면은 의료진에게 보여주는 참고 자료입니다. 의심되면 기다리지 말고 연락하세요.</div></div>`}
function vMeds(){const t=today(),off=db.meds.filter(m=>m.end&&m.end<t),rest=db.meds.filter(m=>!off.includes(m)),on=rest.filter(m=>m.start<=t),next=rest.filter(m=>m.start>t).sort((a,b)=>a.start.localeCompare(b.start));
 const row=m=>{const r=remaining(m);return `<button class="li" data-a="medSheet" data-id="${m.id}"><span class="tag t-${m.type}">${TYPE[m.type]}</span><span class="grow"><span class="t">${esc(m.name)}</span> <span class="s">${esc(m.dose||'')}</span><br><span class="s num">${repKey(m.rep)?repLabel(m)+' ':''}${m.slots.map(s=>esc(s.time)).join(', ')}${m.start>t?` · ${fmtMD(m.start)}부터`:''}${m.end?` · ${fmtMD(m.end)}까지`:''}${r!=null?` · ${r}회분 남음`:''}</span></span>${I.chev}</button>`};
 return `<div class="stack">${head('처방 관리')}<button class="btn" data-a="medSheet">약 또는 주사 추가</button><div class="list">${on.map(row).join('')||'<div class="li"><span class="s">등록된 약이 없습니다.</span></div>'}</div>${next.length?`<section class="sec"><h2 style="font-size:1rem">시작 예정</h2><div class="list">${next.map(row).join('')}</div></section>`:''}${off.length?`<section class="sec"><h2 style="font-size:1rem">끝난 처방</h2><div class="list">${off.map(row).join('')}</div></section>`:''}<div class="note info"><span>처방이 바뀌어도 지난 기록은 그대로 남습니다. 감량처럼 날짜에 맞춰 바뀌는 처방은 약을 눌러 변경 적용일을 넣으세요. 복용량과 중단일은 병원 지시대로 입력하세요.</span></div></div>`}
function vSites(){const log=siteLog().slice(0,30),s=suggestSite(),cnt={};for(const x of siteLog())cnt[x.site]=(cnt[x.site]||0)+1;
 return `<div class="stack">${head('주사 위치 기록')}<div class="note info"><b>다음 추천: ${s?ZONES[s]:'첫 기록 후 표시'}</b><span>직전과 반대쪽에서 가장 오래 쉰 부위를 추천합니다. 병원 지시가 있으면 따르세요.</span></div>${belly(null,false,cnt)}<section class="sec"><h2 style="font-size:1rem">최근 기록</h2><div class="list">${log.map(x=>`<div class="li" style="min-height:44px"><span class="grow"><span class="t">${ZONES[x.site]}</span> <span class="s num">${fmtMD(x.date)} ${esc(x.at)}</span>${x.memo?`<br><span class="s">${esc(x.memo)}</span>`:''}</span></div>`).join('')||'<div class="li"><span class="s">아직 기록이 없습니다.</span></div>'}</div></section><details><summary>배 주사 방법</summary><div><ol>${INJECT_GUIDE.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="small faint">병원에서 배운 방법이 다르면 병원 방법을 따르세요.</div></div></details></div>`}
function belly(sel,tap,cnt){const log=siteLog(),last=log[0]?log[0].site:null,rec=suggestSite();
 const z=(k,c,r)=>{const isLast=last===k;const lab=cnt?`${cnt[k]||0}회`:(rec===k?'추천':isLast?'직전':'');
  return `<button class="zone ${sel===k?'on':''} ${!cnt&&rec===k?'rec':''} ${!cnt&&isLast?'last':''}" style="grid-column:${c};grid-row:${r}" ${tap?`data-a="zone" data-v="${k}"`:'tabindex="-1" disabled'}>${ZONES[k].replace('왼쪽 ','').replace('오른쪽 ','')}<small>${lab||'&nbsp;'}</small></button>`};
 return `<div>${!cnt&&log[0]?`<div class="small muted" style="margin-bottom:6px">직전 주사: ${ZONES[log[0].site]} (${fmtMD(log[0].date)})</div>`:''}<div class="row between small muted" style="padding:0 18px 4px"><b>왼쪽</b><b>오른쪽</b></div><div class="belly">${z('LU',1,1)}${z('LM',1,2)}${z('LL',1,3)}${z('RU',3,1)}${z('RM',3,2)}${z('RL',3,3)}<div class="navel"><i></i><span>배꼽 주변 5cm 제외</span></div></div><div class="small faint" style="text-align:center;margin-top:5px">내가 내려다본 방향입니다</div></div>`}
const isIOS=()=>/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const planSig=x=>x.time+(x.rk?'|'+x.rk:'');
const planLabel=x=>`${x.rk?x.label+' ':''}${x.time}`;
function alarmPlan(){const t=today(),g={};for(const m of db.meds){if(m.end&&m.end<t)continue;const f=nextDue(m,1)[0];if(!f)continue;const r=m.rep&&m.rep.k!=='daily'?m.rep:null,rk=!r?'':r.k==='days'?repKey(r):`n${r.n}.${((diff(m.start,'2000-01-01')%r.n)+r.n)%r.n}`;
  for(const s of m.slots){if(!s.time)continue;const k=s.time+'|'+rk,x=g[k]=g[k]||{time:s.time,rk,rep:r,label:r?repLabel(m):'',start:f,begin:'',end:'',open:false,names:[]},b=m.start>t?m.start:t;if(f<x.start)x.start=f;if(!x.begin||b<x.begin)x.begin=b;if(!m.end)x.open=true;else if(m.end>x.end)x.end=m.end;if(!x.names.includes(m.name))x.names.push(m.name)}}
 const all=Object.values(g),out=[];for(const x of all){const d=x.rk&&all.find(y=>!y.rk&&y.time===x.time&&y.start<=x.start&&(y.open||(!x.open&&y.end>=x.end)));if(d){for(const n of x.names)if(!d.names.includes(n))d.names.push(n)}else out.push(x)}
 return out.sort((a,b)=>a.time.localeCompare(b.time)||a.rk.localeCompare(b.rk))}
function calState(){const c=db.calExport,plan=alarmPlan(),cur=plan.map(planLabel);if(!c)return{st:'none',plan,cur,added:[],rem:[]};const t=today(),old=c.plan||(c.times||[]).map(x=>({sig:x,label:x}));
 const added=plan.filter(x=>{const o=old.find(y=>y.sig===planSig(x));return!o||(!!c.plan&&((x.begin>t&&o.begin!==x.begin)||(o.end||'')!==(x.open?'':x.end)))}).map(planLabel),rem=old.filter(y=>!plan.some(x=>planSig(x)===y.sig)&&!(y.end&&y.end<t)).map(y=>y.label);
 return{st:added.length||rem.length?'changed':'same',plan,cur,added,rem,date:c.date}}
const calToken=x=>x.time.replace(':','')+(x.rk?'_'+x.rk:'')+(x.rk||x.start>today()?'_s'+x.start.replace(/-/g,''):'')+(!x.open&&x.end?'_e'+x.end.replace(/-/g,''):'');
function parseCal(h){const m=h.match(/^#cal=(.+)$/);if(!m)return null;const ds=v=>v?`${v.slice(0,4)}-${v.slice(4,6)}-${v.slice(6)}`:'',out=[];for(const t of m[1].split(',').slice(0,48)){const p=t.match(/^(\d{2})(\d{2})(?:_(w[0-6]{1,7}|n\d{1,2}\.\d{1,2}))?(?:_s(\d{8}))?(?:_e(\d{8}))?$/);if(!p||!/^([01]\d|2[0-3])[0-5]\d$/.test(p[1]+p[2]))return null;const rk=p[3]||'';out.push({time:p[1]+':'+p[2],rk,rep:!rk?null:rk[0]==='w'?{k:'days',days:[...rk.slice(1)].map(Number)}:{k:'every',n:Number(rk.slice(1).split('.')[0])},start:ds(p[4]),end:ds(p[5]),open:!p[5]})}return out.length?out:null}
function buildIcs(list,start){const crlf='\r\n',stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z$/,'Z');
 const out=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Poom//Medicine Reminder//KO','CALSCALE:GREGORIAN','METHOD:PUBLISH'];
 for(const e0 of list){const e=typeof e0==='string'?{time:e0}:e0,t=e.time,hm2=t.replace(':',''),title=`품 ${t} 약 시간`,day=(e.start||start).replace(/-/g,''),r=e.rep,id=e.rk?'-'+e.rk.replace('.','-'):'';let rule=!r?'RRULE:FREQ=DAILY':r.k==='days'?'RRULE:FREQ=WEEKLY;BYDAY='+r.days.map(d=>ICSD[d]).join(','):'RRULE:FREQ=DAILY;INTERVAL='+r.n;if(!e.open&&e.end)rule+=`;UNTIL=${e.end.replace(/-/g,'')}T235959`;out.push('BEGIN:VEVENT',`UID:poom-${hm2}${id}@poom.app`,`DTSTAMP:${stamp}`,`DTSTART:${day}T${hm2}00`,'DURATION:PT5M',rule,`SUMMARY:${title}`,'DESCRIPTION:품을 열어 약과 주사를 기록하세요.','TRANSP:TRANSPARENT','BEGIN:VALARM','ACTION:DISPLAY',`DESCRIPTION:${title}`,'TRIGGER:PT0M','END:VALARM','END:VEVENT')}
 out.push('END:VCALENDAR');return out.join(crlf)+crlf}
function saveIcsLink(list){const blob=new Blob([buildIcs(list,today())],{type:'text/calendar;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='poom-alarm.ics';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000)}
function vAlarm(){const c=calState(),ts=c.plan,ios=isIOS();
 const stat=c.st==='none'?`<div class="note info"><b>앱을 닫아도 알림을 받을 수 있습니다</b><span>캘린더 파일을 한 번 넣으면 약 시간에 캘린더 알림이 뜹니다. 요일, 격일, 시작일, 마지막 날도 함께 들어갑니다.</span></div>`:c.st==='same'?`<div class="note info"><b>캘린더 알림 ${c.cur.length}개가 설정되어 있습니다</b><span>${fmtYMD(c.date)}에 넣은 일정과 지금 일정이 같습니다.</span></div>`:`<div class="note warn"><b>약 일정이 바뀌었습니다</b><span>${c.added.length?`새 일정 ${c.added.map(esc).join(', ')}. `:''}${c.rem.length?`없어진 일정 ${c.rem.map(esc).join(', ')}. `:''}기존 일정을 지우고 새 파일을 넣어주세요.</span></div>`;
 return `<div class="stack">${head('알람 맞추기')}${stat}<section class="sec"><div class="sech"><h2>약 시간표</h2><span class="small muted num">${ts.length}개</span></div><div class="list">${ts.map(x=>`<div class="li"><span class="t num" style="width:58px;flex:none">${esc(x.time)}</span><span class="grow"><span class="s">${x.names.map(esc).join(', ')}</span><br><span class="s num">${esc(x.label||'매일')}${x.start>today()?` · ${fmtMD(x.start)}부터`:''}${!x.open&&x.end?` · ${fmtMD(x.end)}까지`:''}</span></span></div>`).join('')||'<div class="li"><span class="s">약을 등록하면 시간표가 나타납니다.</span></div>'}</div></section><button class="btn ${c.st==='same'?'sec2':''}" data-a="calOpen" ${ts.length?'':'disabled'}>${c.st==='none'?'캘린더 파일 만들기':c.st==='changed'?'캘린더 알림 다시 만들기':'캘린더 파일 다시 만들기'}</button><div class="small faint">일정 제목은 "품 08:00 약 시간"처럼 표시되고 약 이름은 들어가지 않습니다.</div>${(()=>{const fa=db.appts.filter(a=>a.date>=today()&&!a.done).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')));return fa.length?`<section class="sec"><div class="sech"><h2>진료 일정 알림</h2><span class="small muted num">${fa.length}건</span></div><div class="list">${fa.map(apptRow).join('')}</div><button class="btn sec2" data-a="apptIcsAll">아직 넣지 않은 일정 캘린더에 넣기</button><div class="small faint">시간이 있는 일정은 전날 저녁 8시와 당일 아침 7시 30분, 시간이 없는 일정은 전날 저녁 8시와 당일 아침 7시 30분에 알림이 뜹니다. 같은 일정을 두 번 넣으면 두 번 표시될 수 있습니다.</div></section>`:''})()}<section class="sec"><h2 style="font-size:1rem">자세한 사용 방법</h2><div>${calHelp(ios)}</div></section></div>`}
const CAL_IOS=['품에서 파일 보내기를 누릅니다.','공유 창에서 메일을 고르고, 받는 사람에 본인 메일 주소를 넣어 보냅니다.','아이폰 기본 메일 앱에서 받은 메일을 엽니다.','첨부된 poom-alarm.ics 파일을 누릅니다.','모두 추가를 누르고 저장할 캘린더를 고른 뒤 완료를 누릅니다.'];
const CAL_AND=['품에서 파일 보내기를 누릅니다.','화면에 나온 다운로드 알림이나 파일 앱의 다운로드 폴더에서 poom-alarm.ics를 누릅니다.','Samsung 캘린더 또는 Google 캘린더를 고릅니다.','저장 또는 가져오기를 누릅니다. Google 캘린더는 저장할 캘린더를 먼저 고릅니다.'];
const CAL_TIPS=['새 파일을 넣기 전에 기존 품 일정을 지우세요. 지우지 않으면 같은 시간에 알림이 두 번 옵니다.','캘린더 알림은 품과 연결되어 있지 않습니다. 알림을 받은 뒤 품을 열어 완료를 눌러주세요.','처음 넣은 날에는 다음 약 시간에 알림이 뜨는지 꼭 확인하세요.','무음 모드나 집중 모드에서는 소리가 안 나거나 알림이 숨겨질 수 있습니다. 주사처럼 놓치면 안 되는 시간은 시계 알람도 함께 맞추세요.','캘린더 일정은 iCloud나 Google 계정에 동기화될 수 있습니다. 그래서 일정에 약 이름을 넣지 않습니다.','폰을 바꾸면 캘린더 일정이 옮겨졌는지 확인하고, 없으면 파일을 다시 만드세요.'];
function calHelp(ios){const o=l=>`<ol>${l.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`;return `<details ${ios?'open':''}><summary>아이폰에서 캘린더에 넣기</summary><div>${o(CAL_IOS)}<p class="small muted">공유 창이 열리지 않으면 캘린더 파일 만들기 화면의 Safari에서 파일 받기를 누르세요.</p></div></details><details ${ios?'':'open'}><summary>안드로이드에서 캘린더에 넣기</summary><div>${o(CAL_AND)}</div></details><details><summary>약이나 시간이 바뀌었을 때</summary><div><p><b>같은 시간대의 약만 바뀐 경우</b><br>품의 처방만 수정하면 됩니다. 캘린더는 그대로 둡니다.</p><p><b>시간, 요일, 격일, 시작일, 마지막 날이 바뀐 경우</b><br>품의 처방을 수정하면 이 화면과 오늘 화면에 다시 만들라는 안내가 나옵니다.</p>${o(['캘린더 앱에서 기존 "품 ... 약 시간" 일정을 엽니다.','이벤트 삭제를 누르고 이후 모든 이벤트 삭제를 고릅니다.','남은 품 일정도 시간마다 같은 방법으로 지웁니다.','이 화면에서 캘린더 알림 다시 만들기를 누릅니다.','새 파일을 캘린더에 넣습니다.'])}<p><b>마지막 날이 있는 약</b><br>새로 만든 파일에는 마지막 날이 들어 있어 그날 이후 알림이 끝납니다. 이전 버전에서 넣은 일정은 직접 지워주세요.</p></div></details><details><summary>알림이 뜨지 않을 때</summary><div>${o(['캘린더에서 일정을 열어 알림 항목이 이벤트 당시인지 확인합니다.','없음이면 편집에서 이벤트 당시로 바꾸고 이후 모든 이벤트에 저장합니다.','아이폰은 설정 → 앱 → 캘린더 → 알림에서 알림 허용을 켭니다.','안드로이드는 설정 → 애플리케이션 → 캘린더 → 알림을 켭니다.','5분 뒤 시험 일정을 만들어 알림을 확인하고 지웁니다.'])}</div></details><details><summary>꼭 알아둘 점</summary><div><ul>${CAL_TIPS.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></details><details><summary>시계 앱 알람으로 맞추기</summary><div><p class="small muted">소리로 확실히 알리고 싶을 때 사용하세요. 약 시간이 바뀌면 시계 알람도 직접 바꿔야 합니다.</p><p><b>아이폰</b></p><ol><li>시계 앱을 엽니다</li><li>알람 탭에서 + 를 누릅니다</li><li>시간을 고르고 반복에서 모든 요일을 선택합니다</li><li>레이블에 약 이름을 적고 저장합니다</li></ol><p><b>안드로이드</b></p><ol><li>시계 앱을 엽니다</li><li>알람에서 + 를 누릅니다</li><li>시간을 고르고 요일을 모두 선택합니다</li><li>이름에 약 이름을 적고 저장합니다</li></ol></div></details>`}
function calSheet(){const c=calState(),ios=isIOS(),prior=db.calExport;ui.calSent=false;ui.calCleared=!prior;const steps=(ios?CAL_IOS:CAL_AND).slice(1);
 openSheet(`${shh(prior?'캘린더 알림 다시 만들기':'캘린더 파일 만들기')}<div class="small muted num">넣을 알림 ${c.cur.length}개: ${c.cur.map(esc).join(', ')}</div>${prior?`<section class="sec"><h3 class="calstep"><span>1</span>기존 일정 지우기</h3><div class="note warn"><span>지우지 않으면 같은 알림이 두 번 올 수 있습니다.</span></div><ol><li>캘린더 앱에서 내일 날짜를 엽니다.</li><li>품 일정을 눌러 이벤트 삭제를 누릅니다.</li><li>이후 모든 이벤트 삭제를 고릅니다.</li><li>지울 일정: ${(prior.plan?prior.plan.map(x=>x.label):prior.times||[]).map(esc).join(', ')}</li></ol><label class="check"><input type="checkbox" id="calCleared" data-c="calCleared">기존 품 일정을 모두 지웠습니다</label></section>`:''}<section class="sec"><h3 class="calstep"><span>${prior?2:1}</span>파일 보내기</h3><button class="btn" id="calSendBtn" data-a="calSend" ${prior?'disabled':''}>${ios?'파일 보내기':'파일 저장하기'}</button>${ios?`<a class="btn ghost" id="calSafari" href="./#cal=${c.plan.map(calToken).join(',')}" target="_blank" rel="noopener" ${prior?'hidden':''}>공유 창이 안 열리면 Safari에서 파일 받기</a>`:''}</section><section class="sec"><h3 class="calstep"><span>${prior?3:2}</span>캘린더에 넣기</h3><ol>${steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section class="sec"><h3 class="calstep"><span>${prior?4:3}</span>품으로 돌아오기</h3><button class="btn sec2" id="calDoneBtn" data-a="calDone" disabled>캘린더에 넣었습니다</button><div class="small muted">다음 약 시간에 알림이 뜨는지 확인해 주세요.</div></section>`)}
function vCalPage(){const ts=ui.calPage.map(x=>x.time);return `<div class="stack"><div class="ptitle">캘린더 알림 파일</div><div class="note info"><span>이 화면은 파일을 받는 전용 화면입니다. 설정 코드를 넣지 마세요.</span></div><div class="list">${ts.map(t=>`<div class="li" style="min-height:44px"><span class="t num">품 ${esc(t)} 약 시간</span></div>`).join('')}</div><button class="btn" data-a="calPageGet">파일 받기</button><ol><li>파일 받기를 누르고 다운로드를 허용합니다.</li><li>주소창 옆 다운로드 표시를 누릅니다.</li><li>poom-alarm.ics를 누르고 모두 추가를 누릅니다.</li><li>저장할 캘린더를 고르고 완료를 누릅니다.</li><li>이 화면을 닫고 홈 화면의 품 아이콘으로 돌아갑니다.</li><li>캘린더에 넣었습니다를 누릅니다.</li></ol></div>`}
function summaryText(){const p=db.profile,t=today(),from=add(t,-13),g=ga(t),l=[];l.push(`[품 진료 요약] ${fmtYMD(t)}`);if(p.name)l.push(`이름: ${p.name}`);if(g!=null&&!born())l.push(`임신 ${fmtGA(g)}, 예정일 ${fmtYMD(edd())}, 아기 수 ${p.fetus==='unknown'||!p.fetus?'미확인':p.fetus+'명'}`);
 if(p.baseMode==='transfer'&&p.transferDate)l.push(`시술: 이식일 ${fmtYMD(p.transferDate)}, ${p.embryoDay}일 배아`);if(born())l.push(`출산일: ${fmtYMD(p.birthDate)} (산후 ${diff(t,p.birthDate)}일)`);
 l.push('','[현재 처방]');for(const m of db.meds)if(active(m,t))l.push(`- ${m.name} ${m.dose||''} (${repKey(m.rep)?repLabel(m)+' ':''}${m.slots.map(s=>s.time).join(', ')})`);
 const by={};for(let d=from;d<=t;d=add(d,1)){if(d<p.trackingStart)continue;for(const i of slotsFor(d)){const n=i.m.name;by[n]=by[n]||[0,0];by[n][1]++;if(i.rec&&i.rec.s==='done')by[n][0]++}}
 l.push('','[최근 14일 복용]');for(const n of Object.keys(by))l.push(`- ${n}: ${by[n][0]}/${by[n][1]}회`);
 const li=lastInjection();if(li)l.push(`- 마지막 주사: ${fmtYMD(li.date)} ${li.at||''} ${li.site?ZONES[li.site]:''}`);
 const c={};for(let d=from;d<=t;d=add(d,1)){const s=(db.days[d]||{}).sym||{};for(const x of SYM)if(s[x[0]])c[x[1]]=(c[x[1]]||0)+1}
 if(Object.keys(c).length){l.push('','[최근 14일 증상]');for(const k of Object.keys(c))l.push(`- ${k}: ${c[k]}일`)}
 const labs=db.labs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);if(labs.length){l.push('','[최근 수치]');for(const x of labs)l.push(`- ${fmtMD(x.date)} ${x.name} ${x.value} ${x.unit||''}`)}
 const q=db.questions.filter(x=>!x.done);if(q.length){l.push('','[물어볼 질문]');for(const x of q)l.push(`- ${x.text}`)}const ur=usList().filter(r=>r.date<=today()&&r.note).slice(-3);if(ur.length){l.push('','[초음파 소견]');for(const r of ur)l.push(`- ${fmtYMD(r.date)}: ${r.note.replace(/\s*\n\s*/g,' ')}`)}const nu=usList().find(r=>r.date>today());if(nu)l.push(`- 다음 초음파 예정: ${fmtYMD(nu.date)}`);const qa=db.questions.filter(x=>x.done&&x.answer).sort((a,b)=>(b.aDate||'').localeCompare(a.aDate||'')).slice(0,10);if(qa.length){l.push('','[받은 답변]');for(const x of qa)l.push(`- ${x.aDate?fmtYMD(x.aDate)+' ':''}${x.text}: ${x.answer.replace(/\s*\n\s*/g,' ')}`)}return l.join('\n')}
function vSummary(){return `<div class="stack">${head('진료 요약')}<textarea id="sumText" rows="16" readonly style="min-height:320px" aria-label="진료 요약">${esc(summaryText())}</textarea><button class="btn" data-a="copy" data-v="sumText">요약 복사</button><div class="small faint">진료실에서 이 화면을 보여주거나 복사해 메모에 붙일 수 있습니다.</div></div>`}
const SUP_DATE='2026년 11월 9일';
const supDone=x=>!!db.checks['s_'+x.id];
function supNow(){const t=today(),p=db.profile;if(born()){const left=x=>x.dl-diff(t,p.birthDate);return SUPPORT.filter(x=>x.dl&&!supDone(x)&&left(x)>=0).sort((a,b)=>left(a)-left(b)).map(x=>({x,left:left(x)}))}const w=wk(t);if(w==null)return[];return SUPPORT.filter(x=>x.now&&!supDone(x)&&x.now.some(([a,b])=>w>=a&&w<=b)).map(x=>({x}))}
const telify=s=>esc(s).replace(/\d{2,4}-\d{3,4}-\d{4}|\d{4}-\d{4}|\b1\d{2}(?:\d)?\b/g,m=>`<a href="tel:${m.replace(/-/g,'')}">${m}</a>`);
function supItem(x,left){gloSeen.clear();const on=supDone(x),li=a=>a&&a.length?`<ul>${a.map(v=>`<li>${gt(v)}</li>`).join('')}</ul>`:'',links=(x.src||[]).map(k=>L[k]).filter(Boolean);
 return `<div class="supi ${on?'ok':''}"><input type="checkbox" aria-label="${esc(x.t)} 확인 완료" data-c="sup" data-v="${esc(x.id)}" ${on?'checked':''}><details><summary><span class="grow"><span class="t">${esc(x.t)}</span>${x.flag?` <span class="tag t-visit">${esc(x.flag)}</span>`:''}<span class="amt">${esc(x.amt)}</span><span class="s">${esc(x.who)} · ${left!=null?`신청 기한 ${left}일 남음`:esc(x.when)}</span></span>${I.chev}</summary><div>${x.target?`<p><b>대상</b><br>${gt(x.target)}</p>`:''}<div><b>내용</b>${li(x.what)}</div>${x.steps?`<div><b>신청 방법</b><ol>${x.steps.map(v=>`<li>${gt(v)}</li>`).join('')}</ol></div>`:''}${x.docs?`<div><b>준비물</b>${li(x.docs)}</div>`:''}${x.tel?`<p><b>문의</b><br>${telify(x.tel)}</p>`:''}${x.note?`<div class="note warn"><span>${gt(x.note)}</span></div>`:''}${links.length?`<p class="small">${links.map(([n,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(n)}</a>`).join(' · ')}</p>`:''}</div></details></div>`}
function supProgress(){const n=SUPPORT.filter(supDone).length;return `<span class="small muted num" id="supCount">확인 ${n}/${SUPPORT.length}</span>`}
function vSupport(){const tab=ui.sup||'now';let b='';
 if(tab==='now'){const n=supNow(),w=wk();b=`<div class="note info"><b>${born()?'신청 기한이 남은 제도':w!=null?`임신 ${w}주에 챙길 제도`:'임신 기준을 입력하면 시기별로 표시합니다'}</b><span>${n.length?`${n.length}건입니다. 눌러서 신청 방법을 확인하세요.`:'지금 표시할 항목이 없습니다. 다른 탭에서 전체 제도를 볼 수 있습니다.'}</span></div><div class="sups">${n.map(o=>supItem(o.x,o.left)).join('')}</div>`}
 else{const l=SUPPORT.filter(x=>x.cat===tab);b=`${tab==='local'?'<div class="note info"><span>경기도 고양시 기준입니다. 주민등록 주소와 거주 기간 조건을 확인하세요.</span></div>':tab==='free'?'<div class="note info"><span>프리랜서 산모 본인이 확인할 내용만 모았습니다. 진료비 바우처, 부모급여처럼 모두 받는 제도는 다른 탭에 있습니다. 3.3% 소득, 사업자등록, 예술인 등록 여부에 따라 대상이 달라집니다.</span></div>':''}<div class="sups">${l.map(x=>supItem(x)).join('')}</div>`}
 return `<div class="stack">${head('지원 제도')}<div class="row between"><span class="small muted">${SUP_DATE} 확인</span>${supProgress()}</div>${seg('supTab',tab,SUP_CATS)}${b}<div class="small faint">금액과 대상은 바뀔 수 있습니다. 노란 표시는 확정 전이거나 확인이 필요한 항목입니다. 신청 전 공식 창구에서 확인하세요.</div></div>`}
function vBackup(){const t=db.lastBackup;return `<div class="stack">${head('백업과 복원')}<div class="note info"><span>기록은 이 폰에만 있습니다. 2주에 한 번 백업 파일을 만들어 폰의 파일 앱에 보관하세요. ${t?`마지막 백업 ${fmtYMD(t)}.`:''}</span></div><section class="sec"><h2 style="font-size:1rem">내보내기</h2>${SIM?'':'<button class="btn" data-a="exportFile">백업 파일 만들기</button>'}<button class="btn sec2" data-a="exportCopy">백업 내용 복사</button><div class="small muted">백업 파일에는 초음파 사진이 포함되고, 내용 복사에는 포함되지 않습니다.</div><textarea id="bkOut" hidden readonly aria-label="백업 내용"></textarea></section><section class="sec"><h2 style="font-size:1rem">복원</h2><p class="small muted">복원하면 지금 폰의 기록이 백업 내용으로 바뀝니다.</p><div class="fld"><label for="bkFile">백업 파일 선택</label><input id="bkFile" type="file" accept=".json,application/json"></div><div class="fld"><label for="bkText">또는 백업 내용 붙여넣기</label><textarea id="bkText"></textarea></div><button class="btn sec2" data-a="restoreAsk">복원하기</button></section></div>`}
function vSettings(){const p=db.profile;return `<div class="stack">${head('설정')}<section class="sec"><h2 style="font-size:1rem">기본 정보</h2><div class="stack" style="gap:10px">${fld('sName','이름','text',p.name)}${sel('sBase','임신 기준',p.baseMode,[['transfer','배아 이식일'],['edd','출산 예정일(병원 안내)'],['lmp','마지막 생리 시작일']])}${p.baseMode==='transfer'?`<div class="grid2">${fld('sTrans','이식일','date',p.transferDate)}${sel('sEmb','이식한 배아',p.embryoDay,[[3,'3일 배아'],[5,'5일 배아'],[6,'6일 배아'],[2,'2일 배아']])}</div>`:p.baseMode==='edd'?fld('sEdd','출산 예정일','date',p.edd):fld('sLmp','마지막 생리 시작일','date',p.lmp)}${sel('sFetus','아기 수',p.fetus,[['unknown','미확인'],[1,'1명'],[2,'2명'],[3,'3명']])}${fld('sBirth','출산일(출산 후 입력)','date',p.birthDate)}</div></section><section class="sec"><h2 style="font-size:1rem">응급 카드 정보</h2><div class="stack" style="gap:10px"><div class="grid2">${sel('sBlood','혈액형',p.blood,[['','미입력'],['A','A'],['B','B'],['O','O'],['AB','AB']])}${sel('sRh','Rh',p.rh,[['','미입력'],['+','+'],['-','-']])}</div>${fld('sAllergy','약 알레르기','text',p.allergy)}<div class="grid2">${fld('sHosp','담당 병원','text',p.hospital)}${fld('sHospT','병원 전화','tel',p.hospitalTel)}</div><div class="grid2">${fld('sPrevH','이전 병원(선택)','text',p.prevHospital)}${fld('sPrevHT','이전 병원 전화','tel',p.prevHospitalTel)}</div><div class="grid2">${fld('sGuard','보호자','text',p.guardian)}${fld('sGuardT','보호자 전화','tel',p.guardianTel)}</div></div></section><section class="sec"><h2 style="font-size:1rem">안내 방식</h2><div class="stack" style="gap:10px">${sel('sAct','운동 지시',p.activity,[['normal','제한 없음'],['limited','병원에서 운동 제한'],['rest','안정 지시']])}<label class="check"><input type="checkbox" id="sNausea" ${p.nausea?'checked':''}>입덧 모드로 식단 보기</label><label class="check"><input type="checkbox" id="sHide" ${p.hideGuide?'checked':''}><span>주차 안내 숨기기<br><span class="small muted">안내가 부담스러울 때 약 기록과 달력만 남깁니다</span></span></label></div></section><section class="sec"><h2 style="font-size:1rem">화면</h2><div class="stack" style="gap:10px">${SIM?'':sel('sTheme','화면 테마',p.theme,[['system','폰 설정 따르기'],['light','밝게'],['dark','어둡게']])}<label class="check"><input type="checkbox" id="sLarge" ${p.fontLarge?'checked':''}>큰 글씨</label></div></section><button class="btn" data-a="saveSettings">저장</button><section class="sec"><h2 style="font-size:1rem">기록 삭제</h2><button class="btn sec2" data-a="wipeAsk">이 폰의 모든 기록 지우기</button></section></div>`}
const gloCat=c=>GLO_CATS.find(x=>x[0]===c)[1];
function vGloss(){const c=ui.gloCat||'all',list=GLOSS.filter(g=>c==='all'||g[2]===c).sort((a,b)=>a[1].localeCompare(b[1],'ko'));return `<div class="stack">${head('용어 사전')}<input type="text" id="glQ" placeholder="용어 찾기" aria-label="용어 찾기" value="${esc(ui.gloQ||'')}">${seg('gloTab',c,GLO_CATS)}<div class="small muted num" id="glN"></div><div id="glL">${list.map(g=>`<details class="gl" data-s="${esc([g[1],...g[3]].join(' ').toLowerCase())}"><summary>${esc(g[1])}${g[3].length?` <span class="small muted">${esc(g[3][0])}</span>`:''}</summary><div><p>${esc(g[4])}</p></div></details>`).join('')}</div><div class="small faint">일반적인 설명입니다. 내 상황에 대한 판단은 담당 의료진과 공식 창구의 안내를 따르세요.</div></div>`}
function gloFilter(){const e=$('#glQ');if(!e)return;const q=e.value.trim().toLowerCase();ui.gloQ=e.value;let n=0;document.querySelectorAll('.gl').forEach(d=>{const on=!q||d.dataset.s.includes(q);d.hidden=!on;if(on)n++});const c=$('#glN');if(c)c.textContent=`${n}개`}
function termSheet(k){const g=GLOSS.find(x=>x[0]===k);if(!g)return;openSheet(`${shh(esc(g[1]))}<div class="small muted">${gloCat(g[2])}</div><p>${esc(g[4])}</p><div class="small muted">${g[2]==='sup'?'기준과 금액은 바뀔 수 있습니다. 신청 전 공식 창구에서 확인하세요.':'일반적인 설명입니다. 내 상황은 담당 의료진의 설명을 따르세요.'}</div><button class="btn sec2" data-a="go" data-v="gloss" data-close="1">용어 사전 보기</button>`)}
function flightRule(g){const w=Math.floor(g/7),multi=Number(db.profile.fetus)>=2;if(multi&&w>=33)return{lv:'no',t:'탑승 불가(다태 33주 이상)'};if(w>=37)return{lv:'no',t:'탑승 불가(37주 이상)'};if(w>=32)return{lv:'doc',t:'소견서와 서약서 필요'};return{lv:'ok',t:'주수 제한 없음'}}
function flightCheck(label,d){if(!d)return'';const t=today(),g=ga(d);if(d<t)return `<div class="note info"><b>${label}</b><span>지난 날짜입니다. 날짜를 다시 확인해 주세요.</span></div>`;if(g==null||g<0)return `<div class="note info"><b>${label}</b><span>이 날짜의 주수를 계산할 수 없습니다. 설정의 임신 기준을 확인해 주세요.</span></div>`;const r=flightRule(g),w=Math.floor(g/7),x=[];if(r.lv==='doc')x.push(`${fmtMD(add(d,-7))} 이후 발급한 소견서를 준비하세요.`);if(r.lv==='ok')x.push('합병증이나 유산·조산 위험이 있으면 사전 승인이 필요합니다.');if(w<13||w>=36)x.push('전문가들이 항공 여행을 피하도록 권하는 시기입니다.');if(g>=280)x.push('출산 예정일이 지난 날짜입니다.');return `<div class="note ${r.lv==='ok'&&w>=13?'info':r.lv==='no'?'bad':'warn'}"><b>${label} ${fmtYMD(d)} · ${fmtGA(g)}</b><span>${esc(r.t)}. ${x.map(esc).join(' ')}</span></div>`}
function flightBox(){const a=flightCheck('가는 날',ui.flA),b=flightCheck('오는 날',ui.flB);return a||b?a+b:'<div class="small muted">날짜를 넣으면 그날의 임신 주수와 아시아나 기준을 보여줍니다.</div>'}
function vFlight(){const F=FLIGHT,p=db.profile,t=today(),inj=db.meds.some(m=>active(m,t)&&m.type==='injection'),tips=[];if(!lmp())tips.push('설정에서 임신 기준을 입력하면 날짜별 주수를 계산합니다.');if(p.fetus==='unknown'||!p.fetus)tips.push('아기 수가 아직 입력되지 않았습니다. 다태라면 33주부터 탑승할 수 없습니다.');
 return `<div class="stack">${head('항공 여행')}<div class="note warn"><b>예약 전에 담당 병원에 먼저 확인하세요</b><span>아래 기준은 아시아나항공 안내입니다. 항공사마다 다르고 바뀔 수 있습니다.</span></div><section class="sec"><h2 style="font-size:1rem">내 비행 날짜 확인</h2><div class="grid2">${fld('flA','가는 날','date',ui.flA||'',`min="${t}"`)}${fld('flB','오는 날','date',ui.flB||'',`min="${t}"`)}</div><div class="stack" style="gap:8px" id="flR">${flightBox()}</div>${tips.map(x=>`<div class="small muted">${esc(x)}</div>`).join('')}<div class="small faint">앱의 주수는 입력값으로 계산한 값입니다. 소견서의 주수는 병원이 정합니다.</div></section><section class="sec"><h2 style="font-size:1rem">주수별 탑승 기준</h2><div class="list">${F.rules.map(([a,b])=>`<div class="li" style="min-height:48px"><span class="t" style="width:112px;flex:none">${esc(a)}</span><span class="grow s">${esc(b)}</span></div>`).join('')}</div></section><div class="prose">${lst('w','사전 승인이 필요한 경우',F.approve)}${lst('c','32주 이상 37주 미만 준비 서류',F.docs)}${lst('g','소견서에 들어갈 내용',F.cert)}</div><section class="sec"><h2 style="font-size:1rem">공항 서비스</h2><div class="prose">${lst('g','아시아나 임신 고객 서비스',F.svc)}</div><p class="small">${esc(F.seat)}</p><p class="small"><b>문의</b><br>${telify(F.tel)}</p></section><div class="prose">${lst('c','출발 전 준비',F.before)}${lst('g','비행 중 챙길 것',F.inair)}${lst(inj?'w':'c','약과 주사를 가져갈 때',F.meds)}</div>${inj?'<div class="note warn"><b>지금 주사를 맞고 있습니다</b><span>임신과 장시간 비행은 모두 다리 혈전 위험을 높입니다. 항응고 주사 중이라면 비행 가능 여부와 비행 당일 주사 시간을 병원에 꼭 확인하세요.</span></div>':''}<p class="small"><a href="${esc(F.url)}" target="_blank" rel="noopener">아시아나항공 안내 원문 보기</a></p><div class="small faint">${esc(F.date)}에 확인한 내용입니다. 출발 전 탑승 항공사에서 최신 기준을 확인하세요.</div></div>`}
function vGrad(){const p=db.profile;return `<div class="stack">${head('난임병원 졸업 준비')}<div class="note info"><b>보통 8~10주 무렵 산부인과로 옮깁니다</b><span>시기와 약 처방은 다니는 난임병원 안내를 따르세요.</span></div><div class="list">${GRAD.map(x=>`<div class="li" style="align-items:flex-start;padding-block:12px"><label class="row grow" style="gap:12px;align-items:flex-start;cursor:pointer"><input type="checkbox" style="width:22px;height:22px;accent-color:var(--acc);flex:none" data-c="gr" data-v="${x.id}" ${db.checks[x.id]?'checked':''}><span class="grow"><span class="t">${esc(x.t)}</span>${x.note?`<br><span class="s">${esc(x.note)}</span>`:''}</span></label>${x.act?`<button class="link" style="flex:none" data-a="${x.act}">${x.al}</button>`:''}</div>`).join('')}</div><section class="sec"><h2 style="font-size:1rem">응급 카드의 병원</h2><div class="list"><div class="li" style="min-height:44px"><span class="small muted" style="width:76px;flex:none">지금</span><span class="grow">${esc(p.hospital||'미입력')} ${p.hospitalTel?telA(p.hospitalTel):''}</span></div>${p.prevHospital?`<div class="li" style="min-height:44px"><span class="small muted" style="width:76px;flex:none">이전</span><span class="grow">${esc(p.prevHospital)} ${p.prevHospitalTel?telA(p.prevHospitalTel):''}</span></div>`:''}</div></section></div>`}
function hospSheet(){const p=db.profile;openSheet(`${shh('병원 정보 바꾸기')}<div class="small muted">지금: ${esc(p.hospital||'미입력')} ${esc(p.hospitalTel||'')}</div>${fld('hN','새 병원','text','','placeholder="산부인과 이름"')}${fld('hT','새 병원 전화','tel','')}<label class="check"><input type="checkbox" id="hKeep" ${p.hospital?'checked':''}>지금 병원을 응급 카드에 이전 병원으로 남기기</label><button class="btn" data-a="hospSave">저장</button>`)}
function prepSheet(id){const a=db.appts.find(x=>x.id===id);if(!a)return;const q=db.questions.filter(x=>!x.done),ex=lmp()&&!born()?MILESTONES.filter(msVisible).filter(m=>MS_EXAM.includes(m.id)&&!db.checks[m.id]&&msRange(m)[0]<=a.date&&msRange(m)[1]>=a.date):[],bring=['신분증','국민행복카드(진료비 바우처)','복용 중인 약 목록(진료 요약)'];if(gradShow())bring.push('진료의뢰서와 검사 결과지(병원을 옮기는 경우)');if(lmp()&&!born()&&wk(a.date)>=12)bring.push('산모수첩');
 openSheet(`${shh('진료 준비')}<div class="note info"><b>${fmtLong(a.date)}${a.time?' '+esc(a.time):''}</b><span>${esc(a.title)}${a.note?' · '+esc(a.note):''}</span></div><div class="prose">${q.length?lst('c',`물어볼 질문 ${q.length}건`,q.map(x=>x.text)):'<p class="small muted">물어볼 질문이 아직 없습니다. 궁금한 것을 미리 적어 두세요.</p>'}${ex.length?lst('g','이 시기에 받는 검사',ex.map(m=>m.title+(MS_PREP[m.id]?' · '+MS_PREP[m.id]:''))):''}${lst('c','챙길 것',bring)}</div><div class="grid2"><button class="btn sec2" data-a="logQ">질문 목록</button><button class="btn" data-a="go" data-v="summary" data-close="1">진료 요약</button></div>`)}
function visitSheet(id,date){const a=id?db.appts.find(x=>x.id===id):null,d=a?a.date:date;if(!d)return;const u=db.us.find(r=>r.date===d),q=db.questions.filter(x=>!x.done),g=ga(d),ln=g!=null&&g<84&&!born()&&db.labs.some(x=>/hcg/i.test(x.name))?'hCG':'',nx=db.appts.filter(x=>x.date>d&&!x.done).sort((x,y)=>x.date.localeCompare(y.date))[0];ui.visit={id:a?a.id:null,date:d};
 openSheet(`${shh('진료 기록')}<div class="small muted">${fmtLong(d)}${a?' · '+esc(a.title):''}. 들은 내용만 적고 나머지는 비워두세요.</div><section class="sec"><h2 style="font-size:1rem">검사 수치</h2>${[1,2].map(n=>`<div class="grid3">${fld('vN'+n,'항목','text',n===1?ln:'','list="labNames"')}${fld('vV'+n,'수치','text','','inputmode="decimal"')}${fld('vU'+n,'단위','text',n===1&&ln?'mIU/mL':'')}</div>`).join('')}<datalist id="labNames">${[...new Set(['hCG','프로게스테론','에스트라디올','TSH','혈색소',...db.labs.map(x=>x.name)])].map(x=>`<option value="${esc(x)}">`).join('')}</datalist></section><section class="sec"><h2 style="font-size:1rem">초음파</h2><label class="check"><input type="checkbox" id="vUs" ${u?'checked':''}>이 날 초음파 검사를 받았습니다</label><div class="fld"><label for="vUsN">의사 소견</label><textarea id="vUsN" rows="3">${esc(u?u.note:'')}</textarea></div><div class="small muted">사진은 저장한 뒤 기록 → 초음파에서 넣습니다.</div></section>${q.length?`<section class="sec"><h2 style="font-size:1rem">질문 답변</h2>${q.map(x=>`<div class="fld"><label for="vQ_${x.id}">${esc(x.text)}</label><textarea id="vQ_${x.id}" rows="2" data-q="${x.id}" placeholder="답변을 들었다면 적어주세요"></textarea></div>`).join('')}</section>`:''}<section class="sec"><h2 style="font-size:1rem">처방</h2>${sel('vRx','약과 주사','same',[['same','바뀐 것 없음'],['change','바뀌었거나 새로 받음'],['stop','중단하라고 함']])}</section><section class="sec"><h2 style="font-size:1rem">다음 진료</h2>${nx?`<div class="small muted">이미 ${fmtMD(nx.date)} ${esc(nx.title)} 일정이 있습니다. 새로 정했다면 아래에 넣으세요.</div>`:''}<div class="grid2">${fld('vND','날짜','date','',`min="${add(d,1)}"`)}${fld('vNH','시간','time','')}</div>${fld('vNT','내용','text',a&&a.title!=='진료'?a.title:'정기 진료')}</section><div class="fld"><label for="vM">메모</label><textarea id="vM" rows="2">${esc(a&&a.result||'')}</textarea></div><button class="btn" data-a="visitSave">저장</button>`)}
function vHelp(){return `<div class="stack">${head('도움말')}${HELP.map((s,i)=>`<details ${i===0?'open':''}><summary>${esc(s[0])}</summary><div>${s[1]}</div></details>`).join('')}</div>`}
function vSources(){return `<div class="stack">${head('참고 자료')}<div class="list">${SOURCES.map(([t,u])=>`<a class="li" href="${esc(u)}" target="_blank" rel="noopener"><span class="grow t" style="font-weight:500">${esc(t)}</span>${I.chev}</a>`).join('')}</div><p class="small muted">품은 진단이나 처방을 하지 않습니다. 주차 안내, 운동, 식단은 일반 정보이며 시험관 임신, 다태, 항응고 치료 여부에 따라 달라질 수 있습니다. 담당 의료진의 지시를 우선하세요.</p></div>`}

/* 첫 설정 */
function installHint(){const ua=navigator.userAgent,iOS=/iPad|iPhone|iPod/.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),inapp=/KAKAOTALK|NAVER|Instagram|FBAN|FBAV|Line\//i.test(ua),stand=matchMedia('(display-mode: standalone)').matches||navigator.standalone;
 if(stand)return'';if(inapp)return `<div class="note warn"><b>지금은 앱 안 브라우저입니다</b><span>주소를 복사해 ${iOS?'Safari':'Chrome'}에서 열어주세요. 이 화면에서는 설치할 수 없습니다.</span></div>`;
 if(iOS)return `<div class="note warn"><b>먼저 홈 화면에 추가하세요</b><span>Safari 아래쪽 공유 버튼 → 홈 화면에 추가 → 웹 앱으로 열기 켜기 → 추가. 그다음 홈 화면의 품 아이콘에서 시작하세요. Safari에서 입력한 내용은 홈 화면 앱으로 넘어가지 않습니다.</span></div>`;
 return `<div class="note info"><b>홈 화면에 설치하세요</b><span>Chrome 오른쪽 위 ⋮ → 앱 설치 또는 홈 화면에 추가.</span>${window.__bip?'<button class="btn sm" data-a="pwaInstall" style="margin-top:6px">지금 설치</button>':''}</div>`}
function vSetup(){const u=ui.setup;
 if(u.step==='start')return `<div class="stack"><div class="hero"><div class="ptitle" style="font-size:2.2rem">품</div><div class="muted">약과 주사, 임신 주차를 한곳에서 챙깁니다. 기록은 이 폰 안에만 저장됩니다.</div></div>${installHint()}<div class="fld"><label for="code">설정 코드</label><textarea id="code" rows="4" placeholder="받은 설정 코드를 붙여넣으세요">${SIM?esc(window.__simCode||''):''}</textarea></div><button class="btn" data-a="codeGo">설정 코드로 시작</button><button class="btn sec2" data-a="manualGo">직접 입력해서 시작</button><button class="btn ghost" data-a="helpFirst">사용 방법 보기</button></div>`;
 if(u.step==='help')return `<div class="stack"><div class="row"><button class="icb" data-a="setupBack" aria-label="뒤로" style="margin-left:-10px">${I.back}</button><div class="ptitle grow">도움말</div></div>${HELP.map((s,i)=>`<details ${i===0?'open':''}><summary>${esc(s[0])}</summary><div>${s[1]}</div></details>`).join('')}</div>`;
 const s=u.seed,p=s.profile;
 return `<div class="stack"><div class="row"><button class="icb" data-a="setupBack" aria-label="뒤로" style="margin-left:-10px">${I.back}</button><div class="ptitle grow">내용 확인</div></div><div class="stack" style="gap:10px">${fld('fName','이름','text',p.name)}<div class="grid2">${fld('fTrans','배아 이식일','date',p.transferDate)}${sel('fEmb','이식한 배아',p.embryoDay||3,[[3,'3일 배아'],[5,'5일 배아'],[6,'6일 배아'],[2,'2일 배아']])}</div><div class="small muted">이식일이 없으면 시작 후 설정에서 예정일을 입력할 수 있습니다.</div></div><section class="sec"><div class="sech"><h2>약과 주사 시간</h2></div>${s.meds.length?`<div class="list">${s.meds.map((m,i)=>`<div class="li" style="flex-wrap:wrap"><span class="tag t-${m.type}">${TYPE[m.type]}</span><span class="grow"><span class="t">${esc(m.name)}</span> <span class="s">${esc(m.dose||'')}</span>${m.note?`<br><span class="s">${esc(m.note)}</span>`:''}</span><span class="row wrap" style="width:100%">${m.slots.map((x,j)=>`<input type="time" aria-label="${esc(m.name)} ${esc(x.label||'')} 시간" data-c="seedTime" data-m="${i}" data-s="${j}" value="${esc(x.time)}" style="flex:1;min-width:120px">`).join('')}</span></div>`).join('')}</div>`:'<div class="note info"><span>약은 시작 후 더보기의 처방 관리에서 추가할 수 있습니다.</span></div>'}</section><button class="btn" data-a="setupDone">시작하기</button></div>`}
function decodeSetup(t){t=t.trim().replace(/\s+/g,'');if(!/^POOM1\./.test(t))throw new Error('code');const b=t.slice(6).replace(/-/g,'+').replace(/_/g,'/');const bin=atob(b);const u=Uint8Array.from(bin,c=>c.charCodeAt(0));const o=JSON.parse(new TextDecoder().decode(u));if(!o||!o.profile||!Array.isArray(o.meds))throw new Error('code');return o}
function emptyDb(){const t=today();return{v:1,updatedAt:0,profile:{name:'',baseMode:'transfer',transferDate:'',embryoDay:3,edd:'',lmp:'',fetus:'unknown',blood:'',rh:'',allergy:'',hospital:'',hospitalTel:'',guardian:'',guardianTel:'',birthDate:'',activity:'normal',nausea:false,hideGuide:false,fontLarge:false,theme:'system',trackingStart:t},meds:[],doses:{},days:{},labs:[],appts:[],checks:{},questions:[],kicks:[],contractions:[],lastBackup:'',calExport:null,missDismiss:'',us:[],live:{kick:null,cont:null}}}
function buildDb(seed){const d=emptyDb(),t=today();Object.assign(d.profile,seed.profile||{});
 d.meds=(seed.meds||[]).map(m=>Object.assign({id:uid(),type:'oral',name:'',dose:'',note:'',start:t,end:'',stock:'',stockDate:t},m,{slots:(m.slots||[]).map(s=>Object.assign({id:uid()},s))}));
 d.labs=(seed.labs||[]).map(x=>Object.assign({id:uid()},x));d.questions=(seed.questions||[]).map(q=>Object.assign({id:uid(),text:'',done:false,answer:'',qDate:t,aDate:''},typeof q==='string'?{text:q}:q));
 if(seed.seedDay){const sd=seed.seedDay;d.doses[sd]={};for(const m of d.meds)for(const s of m.slots)d.doses[sd][m.id+'|'+s.id]={s:'done',at:'',name:m.name,dose:m.dose,type:m.type,time:s.time,label:s.label||'',site:m.type==='injection'?(seed.seedSite||undefined):undefined}}
 return d}

