function labSheet(id){const x=id?db.labs.find(l=>l.id===id):{date:today(),name:'hCG',value:'',unit:'mIU/mL',note:''};
 openSheet(`${shh(id?'수치 수정':'수치 추가')}${fld('lD','검사일','date',x.date)}<div class="fld"><label for="lN">항목</label><input id="lN" type="text" list="labNames" value="${esc(x.name)}"><datalist id="labNames"><option>hCG</option><option>프로게스테론</option><option>에스트라디올</option><option>혈색소</option><option>공복혈당</option><option>TSH</option></datalist></div><div class="grid2">${fld('lV','수치','text',x.value,'inputmode="decimal"')}${fld('lU','단위','text',x.unit)}</div>${fld('lM','메모','text',x.note)}<button class="btn" data-a="labSave" data-id="${id||''}">저장</button>${id?`<button class="btn sec2" data-a="labDel" data-id="${id}">삭제</button>`:''}`)}
function apptSheet(id,d,title){const x=id?db.appts.find(a=>a.id===id):{date:d||today(),time:'',kind:'visit',title:title||'',note:''};if(!x)return;const t=today(),ex=id&&x.ics&&x.ics!==apptSig(x);
 openSheet(`${shh(id?'일정 수정':'일정 추가')}${sel('aK','종류',x.kind,[['visit','내원'],['procedure','시술·검사']])}${fld('aT','내용','text',x.title,'placeholder="첫 초음파"')}<div class="grid2">${fld('aD','날짜','date',x.date)}${fld('aH','시간','time',x.time)}</div>${fld('aN','메모','text',x.note)}${x.result?`<div class="qa"><b>진료 기록</b><br>${esc(x.result)}</div>`:''}<button class="btn" data-a="apptSave" data-id="${id||''}">저장</button>${id&&x.date>=t?`<button class="btn sec2" data-a="apptIcs" data-v="${id}">${ex?'바뀐 일정 다시 캘린더에 넣기':x.ics?'폰 캘린더에 다시 넣기':'폰 캘린더에 넣기'}</button>${ex?'<div class="small muted">캘린더의 예전 일정은 직접 지워주세요.</div>':''}`:''}${id&&x.date<=t?`<button class="btn sec2" data-a="visitOpen" data-v="${id}" data-close="1">진료 기록${x.done?' 고치기':'하기'}</button>`:''}${id?`<button class="btn sec2" data-a="apptDel" data-id="${id}">삭제</button>`:''}`)}
const hasRec=m=>Object.keys(db.doses).some(dt=>Object.keys(db.doses[dt]).some(k=>k.startsWith(m.id+'|')));
function medRepBox(){const r=ui.mr;if(r.k==='days')return `<div class="chips" style="margin-top:8px">${WD_ORDER.map(d=>`<button class="chip ${r.days.includes(d)?'on':''}" data-a="medDay" data-v="${d}" aria-pressed="${r.days.includes(d)}">${WD[d]}</button>`).join('')}</div>`;if(r.k==='every')return `<div style="margin-top:8px">${fld('mEvery','며칠마다','number',r.n,'min="2" max="60" inputmode="numeric"')}<div class="small muted">2는 격일입니다. 시작일을 첫날로 계산합니다.</div></div>`;return''}
function readRep(){const r=ui.mr;if(r.k==='days'){if(!r.days.length)return false;if(r.days.length===7)return null;return{k:'days',days:r.days.slice().sort((a,b)=>a-b)}}if(r.k==='every'){const e=$('#mEvery'),n=Number(e?e.value:r.n);if(!Number.isInteger(n)||n<1||n>60)return false;r.n=n;return n===1?null:{k:'every',n}}return null}
function medPrev(){const el=$('#mPrev');if(!el)return;const rep=readRep(),f=$('#mSt')||$('#mEff'),st=f?f.value:'',end=$('#mE').value;if(rep===false){el.textContent='반복 설정을 확인해 주세요.';return}if(!st){el.textContent='시작일을 입력해 주세요.';return}const a=nextDue({rep,start:st,end},4);el.textContent=a.length?`다음 일정: ${a.map(x=>`${fmtMD(x)}(${WD[parse(x).getDay()]})`).join(', ')}`:'마지막 날까지 해당하는 날이 없습니다.'}
function medSheet(id){const t=today(),m=id?db.meds.find(x=>x.id===id):{type:'oral',name:'',dose:'',note:'',slots:[{id:uid(),label:'',time:'08:00'}],gap:null,stock:'',start:t,end:''},r=m.rep||{k:'daily'},locked=!!id&&hasRec(m)&&m.start<=t,future=!!id&&m.start>t;ui.ms=JSON.parse(JSON.stringify(m.slots));ui.mr={k:r.k,days:(r.days||[]).slice(),n:r.n||2};
 openSheet(`${shh(id?'처방 수정':'처방 추가')}${sel('mT','종류',m.type,Object.entries(TYPE))}${fld('mN','이름','text',m.name)}${fld('mD','용량','text',m.dose,'placeholder="예: 100mg, 1개"')}<div class="sec"><div class="lbl">하루 시간</div><div id="mSlots">${medSlots()}</div><button class="btn sec2" data-a="slotAdd">시간 추가</button></div>${sel('mRep','반복',r.k,[['daily','매일'],['days','요일 지정'],['every','격일·며칠마다']])}<div id="mRepBox">${medRepBox()}</div><div class="grid2">${locked?fld('mEff','변경 적용일','date',t,`min="${m.start}"`):fld('mSt','시작일','date',m.start)}${fld('mE','마지막 날(선택)','date',m.end)}</div>${locked?'<div class="small muted">바꾼 내용은 이 날부터 적용되고 이전 기록은 그대로 남습니다. 감량 일정은 날짜별로 나눠 넣으세요.</div>':''}<div class="small muted num" id="mPrev"></div><div class="grid2">${fld('mG0','간격 최소(시간)','number',m.gap?m.gap[0]:'')}${fld('mG1','간격 최대(시간)','number',m.gap?m.gap[1]:'')}</div>${fld('mNo','복용 안내','text',m.note)}${fld('mS','남은 수량(회분, 선택)','number',id?(remaining(m)==null?'':remaining(m)):'')}<button class="btn" data-a="medSave" data-id="${id||''}">저장</button>${future?`<button class="btn sec2" data-a="medDel" data-id="${id}">시작 전 처방 지우기</button>`:id?`<button class="btn sec2" data-a="medEnd" data-id="${id}">오늘까지만 사용</button>`:''}<div class="small muted">처방 변경과 중단은 병원 지시를 따르세요.</div>`);medPrev()}
const medSlots=()=>ui.ms.map((s,i)=>`<div class="row" style="margin-bottom:6px"><input type="text" aria-label="시간 이름" placeholder="아침" value="${esc(s.label||'')}" data-c="slotL" data-v="${i}" style="flex:1;min-width:0"><input type="time" aria-label="시간" value="${esc(s.time)}" data-c="slotT" data-v="${i}" style="flex:1;min-width:0"><button class="link" data-a="slotDel" data-v="${i}" aria-label="시간 삭제">삭제</button></div>`).join('');
function usSheet(id){const t=today(),r=id?db.us.find(x=>x.id===id):{date:t,note:''};if(!r)return;const ph=id?usPh(r.date):[],fut=r.date>t,n=id?usNo(r):0;ui.phDate=id&&!fut?r.date:null;
 openSheet(`${shh(id?`초음파 ${n}차 검사`:'초음파 기록 추가')}${fld('uD','검사일','date',r.date)}<div class="fld"><label for="uN">의사 소견</label><textarea id="uN" rows="5" placeholder="예: 아기집 크기, 난황, 심장박동 확인 여부">${esc(r.note||'')}</textarea></div><div class="small muted">앞으로의 날짜를 넣으면 예정된 검사로 저장되고 달력에 표시됩니다.</div><button class="btn" data-a="usSave" data-v="${id||''}">저장</button>${id?`<section class="sec"><div class="sech"><h2>사진</h2><span class="small muted num">${ph.length}장</span></div>${ph.length?`<div class="phs">${ph.map(thumb).join('')}</div>`:''}${fut?'<div class="small muted">검사를 받은 뒤 사진을 넣을 수 있습니다.</div>':`<label class="btn sec2" for="usPhIn">사진 넣기</label><input class="vh" id="usPhIn" type="file" accept="image/*" data-c="photo">`}</section><button class="btn sec2" data-a="usDelAsk" data-v="${id}">기록 지우기</button>`:'<div class="small muted">사진은 저장한 뒤 기록을 열어 넣을 수 있습니다.</div>'}`)}
